'use strict';
const AUDIO_VARIANTS={'menu-power':1,'witch-cast':1,'witch-impact':1,'witch-teleport':1,'witch-storm':1,'shield-block':1,'shield-hit':1,'shield-charge':1,'boss-roar':1,'boss-death':1,'dog-growl':2,'dog-bark':3,'dog-bite':2,'dog-hurt':2,'dog-death':2,'lyra-effort':2,'lyra-pain':1,'lyra-death':1,'lyra-warcry':1,bow:3,'arrow-rain':1,roll:1,swing:3,hit:3,heavy:3,flesh:6,'hero-effort':4,'hero-warcry':1,'hero-pain':2,'hero-death':2,'bandit-death':4};
class GameAudio{
 constructor(){this.ctx=null;this.buffers=new Map();this.loads=new Map();this.repeats=new Map();this.cooldowns=new Map();this.active=new Set();this.paused=true;this.effectVolume=.8;this.musicVolume=.32;this.effectsEnabled=true;this.musicEnabled=true;this.music=new Audio('assets/audio/quarter-forge.mp3');this.menuMusic=new Audio('assets/audio/killquest-menu-iron-rising-v108.mp3?v=iron-rising-v108');this.menuMusic.loop=true;this.menuMusic.preload='metadata';this.backgroundMode='none';this.music.loop=true;this.music.preload='metadata';this.music.volume=this.musicVolume;try{const s=JSON.parse(localStorage.getItem('axe-audio')||'{}');for(const k of ['effectVolume','musicVolume','effectsEnabled','musicEnabled'])if(typeof s[k]===typeof this[k])this[k]=s[k]}catch{}this.music.volume=this.musicVolume;}
 persist(){try{localStorage.setItem('axe-audio',JSON.stringify({effectVolume:this.effectVolume,musicVolume:this.musicVolume,effectsEnabled:this.effectsEnabled,musicEnabled:this.musicEnabled}))}catch{}}
 prepare(){if(!this.ctx){this.ctx=new(window.AudioContext||window.webkitAudioContext)();this.master=this.ctx.createGain();this.master.gain.value=this.effectVolume;this.limiter=this.ctx.createDynamicsCompressor();this.limiter.threshold.value=-12;this.limiter.ratio.value=5;this.master.connect(this.limiter);this.limiter.connect(this.ctx.destination);}this.preload();return Promise.all(this.loads.values())}
 unlock(){try{this.prepare();this.ctx.resume().catch(()=>{})}catch{}}
 preload(){for(const family of ['hero-effort','bandit-death',...Object.keys(AUDIO_VARIANTS).filter(n=>n!=='hero-effort'&&n!=='bandit-death')])for(let i=0;i<AUDIO_VARIANTS[family];i++)this.load(family+'-'+i);for(const n of ['slide','ui','victory','defeat','menu-move','menu-confirm','menu-back'])this.load(n)}
 load(name){if(this.buffers.has(name))return Promise.resolve(this.buffers.get(name));if(this.loads.has(name))return this.loads.get(name);const url='assets/audio/'+name+'.wav?v=witch-v90',cached=globalThis.LoadingScreen?.audio.get(url);const p=(cached?Promise.resolve(cached.slice(0)):fetch(url).then(r=>{if(!r.ok)throw Error('Audio unavailable');return r.arrayBuffer()})).then(b=>this.ctx.decodeAudioData(b)).then(b=>{this.buffers.set(name,b);return b}).catch(()=>null);this.loads.set(name,p);return p}
 async play(family,{x=640,actor=null,rate=1,gain=1}={}){const menu=family.startsWith('menu-')||family==='ui',fanfare=family==='victory'||family==='defeat';if(menu)this.unlock();if(!this.ctx||(!menu&&this.paused)||!this.effectsEnabled||this.effectVolume<=0)return;if(menu){const stamp=performance.now();const key='menu:'+family;if(stamp-(this.cooldowns.get(key)||-1000)<90)return;this.cooldowns.set(key,stamp);}const vocal=/^hero-|^bandit-|^lyra-|^dog-|^boss-/.test(family);const now=performance.now();if(vocal&&actor){const key=actor+':'+family;if(now-(this.cooldowns.get(key)||-1000)<120)return;this.cooldowns.set(key,now)}let name=family;if(!['slide','ui','victory','defeat','menu-move','menu-confirm','menu-back'].includes(family)){const count=AUDIO_VARIANTS[family]||1,previous=this.repeats.get(family);let i=Math.floor(Math.random()*(previous===undefined?count:Math.max(1,count-1)));if(count>1&&previous!==undefined&&i>=previous)i++;this.repeats.set(family,i);name+='-'+i}const buffer=await this.load(name);if(!buffer||(!menu&&this.paused)||!this.effectsEnabled||performance.now()-now>(menu||fanfare?4000:vocal?450:180))return;if(fanfare)for(const active of this.active){try{active.stop()}catch{}this.active.delete(active);}const important=/^(hero|lyra)-(warcry|effort|death)$/.test(family)||family==='bandit-death'||family==='dog-death'||family.startsWith('boss-');if(this.active.size>=20){if(important){const oldest=this.active.values().next().value;try{oldest.stop()}catch{}this.active.delete(oldest)}else return;}if(important&&this.musicEnabled&&!this.paused){this.music.volume=this.musicVolume*.6;clearTimeout(this.duckTimer);this.duckTimer=setTimeout(()=>{this.music.volume=this.musicVolume},Math.ceil((buffer.duration+.15)*1000))}const source=this.ctx.createBufferSource(),amp=this.ctx.createGain(),pan=this.ctx.createStereoPanner();source.buffer=buffer;source.playbackRate.value=rate*(fanfare||menu?1:.97+Math.random()*.06);amp.gain.value=gain*(family==='hero-warcry'?1:family==='hero-effort'?.95:family==='bandit-death'?1:vocal?.65:family==='flesh'?.8:family==='swing'?.55:.7);pan.pan.value=Math.max(-.75,Math.min(.75,(x-640)/850));source.connect(amp);amp.connect(pan);if(menu){amp.gain.value*=this.effectVolume*.45;pan.connect(this.limiter)}else pan.connect(this.master);if(fanfare){this.fanfareSource?.stop();this.fanfareSource=source;}this.active.add(source);source.onended=()=>{this.active.delete(source);source.disconnect();amp.disconnect();pan.disconnect()};source.start()}
 holdMenuMusic(delay=Infinity){clearTimeout(this.menuStartTimer);this.menuNotBefore=delay===Infinity?Infinity:performance.now()+delay;this.menuMusic.pause();if(Number.isFinite(delay))this.menuStartTimer=setTimeout(()=>{if(this.backgroundMode==='menu')this.apply()},delay);}
 startMenuMusic(){if(this.backgroundMode!=='menu'){this.pause();this.backgroundMode='menu';}this.unlock();this.apply();}
 stopBackgroundMusic(){this.backgroundMode='none';this.music.pause();this.menuMusic.pause();}
 startMusic(reset=false){this.backgroundMode='level';this.menuMusic.pause();if(this.fanfareSource){try{this.fanfareSource.stop()}catch{}this.fanfareSource=null;}this.unlock();this.paused=false;this.apply();if(reset)this.music.currentTime=0;if(this.musicEnabled)this.music.play().catch(()=>{})}
 pause(){this.paused=true;this.music.pause();this.menuMusic.pause();for(const s of this.active){try{s.stop()}catch{}}this.apply()}
 resume(){this.startMusic(false)}
 stopMusic(){this.backgroundMode='none';this.pause();this.music.currentTime=0}
 apply(){if(this.master)this.master.gain.setTargetAtTime(this.paused||!this.effectsEnabled?0:this.effectVolume,this.ctx.currentTime,.025);this.music.volume=this.musicVolume;this.menuMusic.volume=this.musicVolume*.85;const audible=this.musicEnabled&&this.musicVolume>0&&(typeof document==='undefined'||!document.hidden);if(!audible||this.paused||this.backgroundMode!=='level')this.music.pause();else this.music.play().catch(()=>{});if(audible&&this.backgroundMode==='menu'&&performance.now()>=(this.menuNotBefore||0))this.menuMusic.play().catch(()=>{});else this.menuMusic.pause()}
 settings(values){Object.assign(this,values);this.persist();this.apply()}
}
const audioMixer=new GameAudio();
if(typeof LoadingScreen!=='undefined')globalThis.__bootAudioMixer=audioMixer;
